fn DeathMatchBattle::new(version: usize, goal: BattlePlanGoal, data: &OperationData, player: &PlayerState) -> DeathMatchBattle

// --- 747행 ---
let mut chats = Vec::<Chat>::new();           // {cap:0, ptr:0x8(dangling), len:0}

// --- 749행 (유일한 분기) ---
if goal.discr == 0 {                          // BattlePlanGoal::TryKill
    let target: usize = goal.+0x8;            // TryKill.__0  (TryKill.__1 은 안 읽음)
    RawVec::<Chat>::grow_one(&mut chats);     // 용량 확보(용량 0 → 성장)
    chats.ptr[0] = Chat::Battle(target, 0);   // 태그 i8 3 @+0, target @+0x8, 0 @+0x10
    chats.len = 1;
}
// else(Support/Response/Avoid) → chats 는 빈 채로 남는다

// --- 753행 ---
let sub = BattlePlanGoal::base_sub_goal(&goal, version, player, data);  // -> {i64,i64} = BattleSubPlanGoal(16B)
// ⚠인자 순서 주의: IR 호출은 (goal, version, player, data). 피호출 쪽 인자명은 (self,_version,player,data)

// --- 754행 ---
let tick: usize = (*data.cache).game.<vtable+0x28>();   // 현재 게임 틱

// --- 752~784행: 구조체 리터럴 (분기 없음, 전 필드 무조건 대입) ---
DeathMatchBattle {
  // 인자/호출에서 오는 값 (판단에 직결되는 3개)
  0x0d0 main_goal        = goal          (memcpy 24B, 753행)
  0x0e8 sub_goal         = sub           (i64 두 개: extractvalue0 -> +0xe8, extractvalue1 -> +0xf0, 753행)
  0x0f8 chats            = chats         (memcpy 24B, 755행)
  0x110 start_tick       = tick          (754행)

  // 센티널
  0x118 flee_die         = 9223372036854775807 (i64::MAX)
  0x17a dive_tower       = None (i8 0xff, 니치)
  0x17b main_objective   = None (i8 0xff, 니치)

  // Option = None (태그 i64 0 만 기록, 페이로드는 미초기화)
  0x000 support_target   = None   (Option<usize>)
  0x010 region           = None   (Option<BattleRegion>)
  0x030 well_runaway     = None   (Option<usize>)
  0x040 death_focus      = None   (Option<usize>)
  0x050 seal_basis       = None   (Option<(usize,usize,usize)>)
  0x070 hold_scene_basis = None   (Option<(usize,usize,usize)>)
  0x090 repo_scene_basis = None   (Option<(usize,usize)>)
  0x0a8 flee_dir         = None   (Option<(i64,i64)>)
  0x0c0 far_noout_since  = None   (Option<usize>)

  // memset 80B (0x120..0x170) 로 일괄 0
  0x120 trade_lean=0  0x128 lean_last_tick=0  0x130 scene_change_tick=0
  0x138 last_act_tick=0  0x140 idle_spec_tick=0  0x148 last_swing_tick=0
  0x150 ep_follow_until=0  0x158 idle_prev_pos=(0,0)  0x168 last_unseal_tick=0

  // bool = false
  0x170 with_dive=false  0x171 help_called=false  0x172 dive_abandoned=false
  0x173 dodge_commit=false  0x174 last_stand=false  0x175 had_ult_ready=false

  // 열거형 = 0번 variant
  0x176 stance          = DeathStance::Commit(0)
  0x177 tactic          = BattleTactic::Standard(0)
  0x178 scene           = DmScene::Stand(0)
  0x179 scene_last_from = DmScene::Stand(0)
  0x17e lean_last_sign  = 0 (i8)
}

// 언와인딩 경로(블록 16): grow_one / base_sub_goal / vtable 호출이 패닉하면
// cleanuppad 에서 chats(Vec<Chat>) 를 drop_glue 로 해제 후 재던짐.

★판단에 직결되는 초기값 요약
 - start_tick 은 '지금 틱' 이므로 이후 모든 경과시간 판정의 기준점이다.
 - flee_die = i64::MAX 라 '도주 중 사망 예정' 비교는 초기엔 항상 미충족.
 - stance=Commit / scene=Stand / tactic=Standard 라 전투는 '교전 확정 자세 + 정지 장면 + 표준 전술' 로 시작한다.
 - TryKill 목표일 때만 팀 채팅에 Chat::Battle(target,0) 이 한 건 예약된다(다른 목표는 무음).
 - 나머지 모든 상태(지역, 봉인/홀드/재배치 기준점, 도주방향, 다이브 타워, 팀 오브젝티브)는 None 이라
   첫 update 에서 각 판정이 '기준 없음' 경로로 진입한다.
